        const addRelative = (name: string, rel: string) => {
            if (name !== 'null' && name.trim() !== '') {
                const nParts = name.split(/\s+/);
                relatives.push({
                    FirstName: nParts[0],
                    LastName: nParts[nParts.length - 1],
                    Relationship: rel
