        ["LastName"] = lastName,
        ["Birthday"] = bday.ToString("yyyy-MM-dd"),
        ["Age"] = age,
        ["Relatives"] = new JsonArray()
    };

    var relatives = new List<(string First, string Last, string Rel)>();
    if (cols[3].Trim() != "null") 
